ALTER TYPE "file_kind" ADD VALUE IF NOT EXISTS 'EXPENSE_DOCUMENT';
ALTER TYPE "sequence_scope" ADD VALUE IF NOT EXISTS 'PURCHASE_ORDER';
ALTER TYPE "sequence_scope" ADD VALUE IF NOT EXISTS 'EXPENSE';
ALTER TYPE "sequence_scope" ADD VALUE IF NOT EXISTS 'SUPPLIER_PAYMENT';
CREATE TYPE "supplier_status" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "purchase_order_status" AS ENUM ('DRAFT','SUBMITTED','APPROVED','REJECTED','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED');
CREATE TYPE "expense_status" AS ENUM ('DRAFT','SUBMITTED','APPROVED','REJECTED','PARTIALLY_PAID','PAID','CANCELLED');
CREATE TYPE "supplier_payment_status" AS ENUM ('SUCCESS','VOIDED');

CREATE TABLE "suppliers" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"tax_id" TEXT,"phone" TEXT,"email" CITEXT,"address" TEXT,"payment_terms_days" INTEGER NOT NULL DEFAULT 30,"status" "supplier_status" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "suppliers_pkey" PRIMARY KEY("id"),CONSTRAINT "suppliers_payment_terms_check" CHECK("payment_terms_days">=0),CONSTRAINT "suppliers_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "suppliers_school_id_code_key" ON "suppliers"("school_id","code");CREATE INDEX "suppliers_school_id_status_name_idx" ON "suppliers"("school_id","status","name");

CREATE TABLE "expense_categories" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"status" "reference_status" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "expense_categories_pkey" PRIMARY KEY("id"),CONSTRAINT "expense_categories_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "expense_categories_school_id_code_key" ON "expense_categories"("school_id","code");CREATE INDEX "expense_categories_school_id_status_name_idx" ON "expense_categories"("school_id","status","name");

CREATE TABLE "purchase_orders" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"reference" TEXT NOT NULL,"supplier_id" UUID NOT NULL,"status" "purchase_order_status" NOT NULL DEFAULT 'DRAFT',"subtotal" BIGINT NOT NULL,"total_amount" BIGINT NOT NULL,"expected_date" DATE,"notes" TEXT,"decision_reason" TEXT,"requested_by" UUID NOT NULL,"approved_by" UUID,"submitted_at" TIMESTAMPTZ(3),"approved_at" TIMESTAMPTZ(3),"received_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "purchase_orders_pkey" PRIMARY KEY("id"),CONSTRAINT "purchase_orders_amount_check" CHECK("subtotal">=0 AND "total_amount">=0),CONSTRAINT "purchase_orders_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "purchase_orders_supplier_id_fkey" FOREIGN KEY("supplier_id") REFERENCES "suppliers"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "purchase_orders_reference_key" ON "purchase_orders"("reference");CREATE INDEX "purchase_orders_school_id_status_created_at_idx" ON "purchase_orders"("school_id","status","created_at" DESC);CREATE INDEX "purchase_orders_school_id_supplier_id_created_at_idx" ON "purchase_orders"("school_id","supplier_id","created_at" DESC);CREATE INDEX "purchase_orders_pending_idx" ON "purchase_orders"("school_id","submitted_at") WHERE "status"='SUBMITTED';

CREATE TABLE "purchase_order_lines" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"purchase_order_id" UUID NOT NULL,"description" TEXT NOT NULL,"quantity" DECIMAL(14,3) NOT NULL,"unit_price" BIGINT NOT NULL,"line_total" BIGINT NOT NULL,CONSTRAINT "purchase_order_lines_pkey" PRIMARY KEY("id"),CONSTRAINT "purchase_order_lines_values_check" CHECK("quantity">0 AND "unit_price">0 AND "line_total">0),CONSTRAINT "purchase_order_lines_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "purchase_order_lines_purchase_order_id_fkey" FOREIGN KEY("purchase_order_id") REFERENCES "purchase_orders"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "purchase_order_lines_purchase_order_id_idx" ON "purchase_order_lines"("purchase_order_id");

CREATE TABLE "expenses" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"reference" TEXT NOT NULL,"supplier_id" UUID NOT NULL,"category_id" UUID NOT NULL,"purchase_order_id" UUID,"invoice_number" TEXT,"invoice_date" DATE NOT NULL,"due_date" DATE NOT NULL,"description" TEXT NOT NULL,"amount" BIGINT NOT NULL,"paid_amount" BIGINT NOT NULL DEFAULT 0,"status" "expense_status" NOT NULL DEFAULT 'DRAFT',"attachment_file_id" UUID,"decision_reason" TEXT,"created_by" UUID NOT NULL,"approved_by" UUID,"submitted_at" TIMESTAMPTZ(3),"approved_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "expenses_pkey" PRIMARY KEY("id"),CONSTRAINT "expenses_amount_check" CHECK("amount">0 AND "paid_amount">=0 AND "paid_amount"<="amount"),CONSTRAINT "expenses_dates_check" CHECK("due_date">="invoice_date"),CONSTRAINT "expenses_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "expenses_supplier_id_fkey" FOREIGN KEY("supplier_id") REFERENCES "suppliers"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "expenses_category_id_fkey" FOREIGN KEY("category_id") REFERENCES "expense_categories"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "expenses_purchase_order_id_fkey" FOREIGN KEY("purchase_order_id") REFERENCES "purchase_orders"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "expenses_attachment_file_id_fkey" FOREIGN KEY("attachment_file_id") REFERENCES "files"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "expenses_reference_key" ON "expenses"("reference");CREATE UNIQUE INDEX "expenses_school_id_supplier_id_invoice_number_key" ON "expenses"("school_id","supplier_id","invoice_number");CREATE INDEX "expenses_school_id_status_due_date_idx" ON "expenses"("school_id","status","due_date");CREATE INDEX "expenses_school_id_supplier_id_due_date_idx" ON "expenses"("school_id","supplier_id","due_date");CREATE INDEX "expenses_purchase_order_id_idx" ON "expenses"("purchase_order_id");CREATE INDEX "expenses_payable_due_idx" ON "expenses"("school_id","due_date") WHERE "status" IN ('APPROVED','PARTIALLY_PAID');

CREATE TABLE "supplier_payments" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"expense_id" UUID NOT NULL,"reference" TEXT NOT NULL,"amount" BIGINT NOT NULL,"method" "payment_method" NOT NULL,"external_reference" TEXT,"paid_at" TIMESTAMPTZ(3) NOT NULL,"status" "supplier_payment_status" NOT NULL DEFAULT 'SUCCESS',"cash_session_id" UUID,"idempotency_key" TEXT NOT NULL,"note" TEXT,"created_by" UUID NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "supplier_payments_pkey" PRIMARY KEY("id"),CONSTRAINT "supplier_payments_amount_check" CHECK("amount">0),CONSTRAINT "supplier_payments_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "supplier_payments_expense_id_fkey" FOREIGN KEY("expense_id") REFERENCES "expenses"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "supplier_payments_cash_session_id_fkey" FOREIGN KEY("cash_session_id") REFERENCES "cash_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "supplier_payments_reference_key" ON "supplier_payments"("reference");CREATE UNIQUE INDEX "supplier_payments_idempotency_key_key" ON "supplier_payments"("idempotency_key");CREATE INDEX "supplier_payments_school_id_paid_at_idx" ON "supplier_payments"("school_id","paid_at" DESC);CREATE INDEX "supplier_payments_expense_id_status_idx" ON "supplier_payments"("expense_id","status");

ALTER TABLE "cash_session_movements" ADD COLUMN "supplier_payment_id" UUID;
CREATE UNIQUE INDEX "cash_session_movements_supplier_payment_id_key" ON "cash_session_movements"("supplier_payment_id");
ALTER TABLE "cash_session_movements" ADD CONSTRAINT "cash_session_movements_supplier_payment_id_fkey" FOREIGN KEY("supplier_payment_id") REFERENCES "supplier_payments"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
